import {it,expect} from 'vitest';import vm from 'node:vm';import {readFileSync} from 'node:fs';import * as C from '../../store-orders/core.js';
const ctx={console,Uint8Array,ArrayBuffer,TextEncoder,TextDecoder};ctx.globalThis=ctx;vm.createContext(ctx);vm.runInContext(readFileSync('../inventory/assets/xlsx.full.min.js','utf8'),ctx);const X=ctx.XLSX;
function master(rows){const w=X.utils.book_new();X.utils.book_append_sheet(w,X.utils.aoa_to_sheet(rows),'主檔');return C.parseMaster(X.read(X.write(w,{type:'array',bookType:'xlsx'}),C.READ_OPTIONS),X,'snapshot-1');}
it('實際xlsx讀入成本價，不混用進貨價；採用後成本與版本為獨立快照',()=>{const m=master([['貨號','品名','進貨價','成本價'],['00001','商品',999,100.1234]]),p=C.matchProduct(m,'00001').matches[0],item=C.applyProduct({quantity:1,unitPrice:300},p);expect(item.costSnapshot).toEqual({sku:'00001',value:'100.1234',field:'成本價',masterVersion:'snapshot-1',status:'provided'});p.costSnapshot.value='777';expect(item.costSnapshot.value).toBe('100.1234');expect(item.unitPrice).toBe(300);});
it('缺成本欄或成本欄重複不猜來源，同貨號不同成本必須確認對應',()=>{for(const rows of [[['貨號','品名','進貨價'],['S','商品',100]],[['貨號','品名','成本價','成本價'],['S','商品',100,200]]])expect(C.matchProduct(master(rows),'S').matches[0].costSnapshot.status).toBe('missing_or_ambiguous');const m=master([['貨號','品名','成本價'],['S','商品',100],['S','商品',200]]);expect(C.matchProduct(m,'S').status).toBe('ambiguous');});
